            return f_rowingmachine;
        case 14:
            if (count) *count = sizeof(f_ropeskipping) / sizeof(f_ropeskipping[0]);
            if (parser) *parser = "RopeSkippingReportParser";
            return f_ropeskipping;
        case 15:
            if (count) *count = sizeof(f_hiking) / sizeof(f_hiking[0]);
