static int cmp_name(const void *key, const void *elem) {
    return strcmp((const char *)key, ((const SchemaFieldId *)elem)->name);
}

int mi_fitness_schema_field_id(const char *name) {
    if (name == NULL) return MI_FITNESS_FIELD_UNKNOWN;
    const SchemaFieldId *hit = bsearch(name, schema_ids, sizeof(schema_ids) / sizeof(schema_ids[0]), sizeof(schema_ids[0]), cmp_name);
    return hit != NULL ? hit->id : MI_FITNESS_FIELD_UNKNOWN;
}

